INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('02d0fa4b711d5cb2b1f70147f9c223b8','四十二人惨案','','惨案','民国','1937','安徽','池州','安徽 池州','0','42','四十二人惨案是民国时期发生的一起造成四十二人死亡的惨案，因史料记载有限，具体发生时间、地点及经过尚不明确。该事件在部分地方史志或抗战史料中或有提及，但缺乏权威、详细的档案记录，难以确证其完整背景与责任主体。目前可确认的是事件造成四十二人遇难，属于民国时期较大规模的群体伤亡事件之一。由于相关史料散佚或记载简略，建议结合地方档案、民国报刊及口述史料进一步考证。','["\\u56DB\\u5341\\u4E8C\\u4EBA\\u60E8\\u6848","\\u6C11\\u56FD\\u60E8\\u6848","\\u7FA4\\u4F53\\u4F24\\u4EA1","\\u5730\\u65B9\\u53F2\\u5FD7","\\u53F2\\u6599\\u5F85\\u8003"]','2026-09-11 08:31:05.246120','2026-09-16 09:28:16.649238');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('04284af2e1695625b1775e2e86057b05','平顶山惨案','平顶山事件、抚顺平顶山惨案','屠杀惨案','民国','1932','辽宁省','抚顺市','抚顺煤矿平顶山村','0','3000','平顶山惨案是九一八事变后日本关东军于1932年9月16日在辽宁省抚顺市平顶山村制造的大规模屠杀事件。1932年9月15日，辽宁民众抗日自卫军袭击了抚顺煤矿，日军为报复并镇压抗日力量，于次日包围平顶山村，将全村约3000名居民驱赶到村南洼地，用机枪扫射并用刺刀刺杀，随后焚毁全村房屋，遇难者遗体被集中掩埋。此次屠杀造成约3000名平民死亡，其中多为老人、妇女和儿童，是日本侵华期间较早的大规模屠杀惨案之一，也是研究九一八事变后日军暴行的重要史料。战后，中国政府在此建立平顶山惨案遗址纪念馆，以纪念遇难同胞。','["\\u5E73\\u9876\\u5C71\\u60E8\\u6848","\\u629A\\u987A","\\u4E5D\\u4E00\\u516B\\u4E8B\\u53D8","\\u65E5\\u519B\\u66B4\\u884C","\\u5927\\u5C60\\u6740","\\u8FBD\\u5B81","1932\\u5E74"]','2026-09-11 08:31:05.246120','2026-09-16 09:26:22.890602');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('05bd4988c5d75d278dd41322a624f72b','淞沪会战','八一三事变、第二次淞沪抗战','会战','民国','1937','上海市','上海市','上海及周边地区（虹口、杨树浦、宝山、罗店、大场、四行仓库等）','1','0','淞沪会战是1937年8月13日至11月12日中国军队与日本侵略军在上海及周边地区展开的大规模会战。8月13日，中国军队向虹口、杨树浦日军据点发起进攻，会战爆发。此后双方不断增兵，中国军队先后投入约70万兵力，日军投入约25万兵力。战役分为围攻日军据点、沿江防御、罗店争夺、大场失守、四行仓库保卫战及最终撤退等阶段。中国军队在装备劣势下顽强抵抗，伤亡约25万至30万人，日军伤亡约4万至9万人。11月12日，中国军队全线撤退，上海沦陷。淞沪会战粉碎了日本“三个月灭亡中国”的速战速决计划，为中国沿海工业内迁和战略物资转移赢得了时间，推动了全国抗日民族统一战线的形成，是抗日战争全面爆发后的首次大规模会战。','["\\u6DDE\\u6CAA\\u4F1A\\u6218","\\u516B\\u4E00\\u4E09\\u4E8B\\u53D8","\\u6297\\u65E5\\u6218\\u4E89","\\u4E0A\\u6D77","\\u56DB\\u884C\\u4ED3\\u5E93","\\u4E2D\\u65E5\\u4F1A\\u6218"]','2026-09-11 08:31:05.246120','2026-09-16 09:26:15.949549');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('0698c1c0080e5df89abbeb626b7b808c','厚和大惨案','厚和惨案','屠杀惨案','抗日战争时期','1937','绥远省','归绥（今呼和浩特）','厚和市（今呼和浩特市）','0','1','厚和大惨案指1937年日军侵占绥远归绥（后改称厚和市，今呼和浩特）前后，对当地抗日军民及无辜民众实施的屠杀与暴行。1937年10月，日军攻占归绥，随后在城内及周边地区搜捕抗日人员、中国军队散兵与疑似抵抗者，成批抓捕并杀害，同时纵兵劫掠、奸淫，造成大量平民伤亡和财产损失。因史料散佚，具体遇难人数尚无确切统计，但该事件与日军在绥远地区的其他暴行共同构成其侵华罪证，是呼和浩特地区抗战记忆的重要组成部分。','["\\u539A\\u548C","\\u5F52\\u7EE5","\\u7EE5\\u8FDC","\\u65E5\\u519B\\u66B4\\u884C","\\u6297\\u65E5\\u6218\\u4E89","\\u547C\\u548C\\u6D69\\u7279","\\u5C60\\u6740"]','2026-09-11 08:31:05.246120','2026-09-16 09:26:05.515499');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('07ac6018f88156439253cdb14e379c68','捡门惨案','','惨案','民国','1937','江西','南昌','江西 南昌','0','1','捡门惨案一名在现有公开史料中未见可靠记载，所指时间、地点与经过均不明确，无法确证其具体内容。检索民国时期及抗日战争时期的惨案名录、地方志与报刊资料，均未发现与“捡门惨案”直接对应的条目，疑为名称讹误、地方俗称或口传失实。因缺乏可考史料，本条目暂无法提供事件概述、伤亡人数与历史影响等信息，相关字段留空，待进一步查证。','["\\u6361\\u95E8\\u60E8\\u6848","\\u6C11\\u56FD\\u60E8\\u6848","\\u6297\\u65E5\\u6218\\u4E89\\u65F6\\u671F","\\u53F2\\u6599\\u5F85\\u8003","\\u540D\\u79F0\\u5B58\\u7591"]','2026-09-11 08:31:05.246120','2026-09-16 09:29:14.377817');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('0be72fcdfca05b2d8e2ed0fb71f0f312','成安惨案','成安大屠杀','日军屠杀惨案','抗日战争时期','1937','河北省','成安县','河北省成安县城及周边村庄','0','5300','1937年10月，日军沿平汉铁路南侵，10月24日攻陷河北省成安县城。日军入城后对城内居民和已放下武器的中国守军进行大规模屠杀，持续数日，遇难者达五千余人，城内多处井窖、坑塘被尸体填满，许多家庭被灭门。日军还纵火焚烧房屋，县城几成废墟。此次惨案是抗日战争初期日军在华北制造的重大暴行之一，与正定惨案、梅花镇惨案等共同构成日军侵华罪行的铁证，战后成安县建有纪念设施以悼念遇难同胞。','["\\u6210\\u5B89\\u60E8\\u6848","\\u6210\\u5B89\\u5927\\u5C60\\u6740","\\u6CB3\\u5317\\u6210\\u5B89","1937\\u5E74","\\u65E5\\u519B\\u66B4\\u884C","\\u6297\\u65E5\\u6218\\u4E89","\\u5E73\\u6C49\\u94C1\\u8DEF","\\u534E\\u5317\\u60E8\\u6848"]','2026-09-11 08:31:05.246120','2026-09-16 09:29:08.487876');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('1147970d1b1551db8f4cf274422f38da','玉田大抓捕惨案','','惨案','民国','1937','河北省','唐山市','玉田县','0','1','玉田大抓捕惨案是民国时期发生在河北省玉田县的一起大规模抓捕事件。玉田县位于冀东地区，抗日战争时期属晋察冀抗日根据地边缘地带，日伪政权与抗日武装在此反复争夺。据现有资料，日伪当局在玉田县境内实施大规模搜捕行动，抓捕当地抗日人员及无辜群众，造成人员伤亡与民众恐慌。该事件具体发生时间、抓捕人数及详细经过，因史料记载有限，尚待进一步考证。','["\\u7389\\u7530","\\u5927\\u6293\\u6355","\\u5180\\u4E1C","\\u65E5\\u4F2A","\\u60E8\\u6848"]','2026-09-11 08:31:05.246120','2026-09-16 09:29:03.719364');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('16b7f0fc8f0b56e89674bb9bfd3b16ad','石洞惨案','','惨案','民国','1941','广东省','台山市','台山市赤溪镇石洞村一带','0','1','石洞惨案是抗日战争时期发生在广东省台山市赤溪镇石洞村一带的一起日军屠杀平民事件。1941年，侵华日军在台山沿海地区登陆，窜扰赤溪、田头等地，所到之处烧杀抢掠。石洞村及附近村落民众在日军扫荡中遭到屠杀，房屋被焚毁，财物被劫掠，具体伤亡人数因史料记载不一而难以确证。该惨案是日军在粤中沿海地区实施侵略暴行的组成部分，反映了抗战时期广东沿海民众所遭受的深重灾难。','["\\u77F3\\u6D1E\\u60E8\\u6848","\\u53F0\\u5C71","\\u8D64\\u6EAA","\\u6297\\u65E5\\u6218\\u4E89","\\u65E5\\u519B\\u66B4\\u884C","\\u5E7F\\u4E1C\\u6CBF\\u6D77"]','2026-09-11 08:31:05.246120','2026-09-16 09:28:55.794549');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('18aefee7a7275e0cbcd2db3d090ed25b','雒贵琦惨案','','惨案','抗日战争时期','1937','山西','吕梁','山西 吕梁','0','1','伪职：石门墕据点伪维持会总头目；罪行：土豪劣绅投敌；盘踞石门墕据点，抓捕、悬赏缉拿我方干部；引日伪军制造雒贵琦惨案，残害大批抗日军民。；结局：武工队锄奸击毙','[]','2026-09-11 08:31:05.246120','2026-09-11 08:31:05.246120');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('1d475a6135c85af1bd426c5ae5188cef','七七事变','卢沟桥事变','军事冲突/侵略暴行','民国','1937','河北省','北京市','卢沟桥、宛平城','1','0','1937年7月7日夜，日军在北平西南卢沟桥附近演习，借口一名士兵失踪，要求进入宛平县城搜查，遭中国守军拒绝。日军随即炮轰宛平城，向卢沟桥发动进攻。中国第29军37师219团奋起抵抗，揭开全国抗日战争的序幕。事变后，日军不断增兵，7月28日大举进攻北平，29日占领北平，30日占领天津。七七事变是日本帝国主义全面侵华战争的起点，也是中国全民族抗战的开端，促使国共两党合作抗日，对远东及世界反法西斯战争格局产生深远影响。','["\\u4E03\\u4E03\\u4E8B\\u53D8","\\u5362\\u6C9F\\u6865\\u4E8B\\u53D8","\\u6297\\u65E5\\u6218\\u4E89","\\u7B2C29\\u519B","\\u5B9B\\u5E73\\u57CE","\\u5168\\u9762\\u6297\\u6218"]','2026-09-11 08:31:05.246120','2026-09-16 09:28:41.504041');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('292590438cdd5d278dedc18d3bf0afdc','亳二区惨案','','惨案','抗日战争时期','1937','安徽省','亳州市','亳县第二区（今亳州市谯城区一带）','0','1','亳二区惨案是抗日战争时期发生在安徽省亳县第二区的一起日军屠杀事件。据地方史志及抗战史料记载，日军侵占亳县期间，多次对周边乡村进行扫荡，在亳县第二区境内制造了杀害无辜民众的暴行。具体发生时间、经过及伤亡人数因现存史料有限，尚待进一步考证。该惨案是日军在皖北地区实施侵略暴行的组成部分，反映了抗战时期沦陷区民众所遭受的深重苦难，是研究亳州地方抗战史和日军侵华罪行的重要史料线索。','["\\u4EB3\\u4E8C\\u533A\\u60E8\\u6848","\\u4EB3\\u53BF","\\u65E5\\u519B\\u66B4\\u884C","\\u6297\\u65E5\\u6218\\u4E89","\\u7696\\u5317","\\u60E8\\u6848"]','2026-09-11 08:31:05.246120','2026-09-16 09:28:36.038029');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('294bfa2599055993b20919f7038b273c','起义警察惨案','','惨案','民国','1937','内蒙古','通辽','内蒙古 通辽','0','1','起义警察惨案所指不明确，缺乏可靠史料可考。检索民国时期与抗日战争时期史料，未见以“起义警察惨案”为专名的历史事件记载。民国时期各地警察参与起义或哗变后遭镇压的事件虽偶有发生，但均无以此名称定性的权威记录，亦无法确证其发生时间、地点、经过与伤亡人数。为避免编造史实，本条目暂不提供具体叙述，相关字段留空，待发现可靠档案、地方志或报刊记载后再行补充。','["\\u8D77\\u4E49\\u8B66\\u5BDF","\\u6C11\\u56FD\\u8B66\\u5BDF","\\u8B66\\u5BDF\\u8D77\\u4E49","\\u60E8\\u6848","\\u53F2\\u6599\\u5F85\\u8003"]','2026-09-11 08:31:05.246120','2026-09-16 09:28:31.016607');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('2c7fe12082fc5d51b5a359fb8fe28c7d','万章惨案','','惨案','民国','1937','山西','晋城','山西 晋城','0','1','万章惨案为民国时期发生的一起惨案，因现存可考史料有限，其具体发生时间、地点、经过及伤亡人数尚待进一步查证。该事件名称见于部分地方史志与抗战时期惨案调查资料，通常被归入日军侵华暴行或地方武装冲突造成的平民伤亡事件之列。由于相关档案、报刊及口述史料尚未系统整理，事件细节存在较大空白，需结合地方志、民国档案及战后调查材料继续考证，以免以讹传讹。','["\\u4E07\\u7AE0\\u60E8\\u6848","\\u6C11\\u56FD\\u60E8\\u6848","\\u6297\\u65E5\\u6218\\u4E89","\\u5730\\u65B9\\u53F2\\u5FD7","\\u65E5\\u519B\\u66B4\\u884C"]','2026-09-11 08:31:05.246120','2026-09-16 09:28:25.692497');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('375828bc29e155f489dcec4afd71226d','东张万人坑惨案','','惨案','抗日战争时期','1937','','','','0','1','东张万人坑惨案是抗日战争时期日军在华北地区制造的一起集体屠杀事件，因事发地俗称“东张”且遗骸集中掩埋形成“万人坑”而得名。目前公开史料中对该惨案的具体发生时间、所属省份与市县、遇难人数等关键信息记载不一，尚缺乏权威档案或方志的明确佐证。综合抗战时期日军在华北多次制造“万人坑”式屠杀的背景，该事件应属日军扫荡或清乡过程中对平民与抗日人员的集体杀害，遇难者被弃置于坑中，成为日军侵华暴行的又一见证。由于史料零散，具体经过与伤亡数字有待进一步查证。伪职：伪浮山县县长；罪行：建立浮山伪政权，设立新民会、剿共委员会，制造东张万人坑惨案，残害大量百姓临汾新闻网。；结局：县城收复后逮捕判刑','["\\u4E1C\\u5F20\\u4E07\\u4EBA\\u5751","\\u6297\\u65E5\\u6218\\u4E89","\\u65E5\\u519B\\u66B4\\u884C","\\u96C6\\u4F53\\u5C60\\u6740","\\u4E07\\u4EBA\\u5751","\\u534E\\u5317"]','2026-09-11 08:31:05.246120','2026-09-16 09:26:37.991207');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('3c17ef6a76c35bf3a4be045160b4c91b','归还兵惨案','','惨案','民国','1937','内蒙古','通辽','内蒙古 通辽','0','1','归还兵惨案所指事件缺乏可靠史料记载，名称含义不明确，可能为地方性小规模冲突或民间口传事件，具体发生时间、地点、经过及伤亡情况均无法确证。检索民国时期及抗日战争时期相关史料，未见以“归还兵惨案”为名的正式记录，亦无权威档案、报刊或方志佐证。为避免编造史实，本条目暂留空处理，待发现可靠史料后再行补充。','["\\u5F52\\u8FD8\\u5175","\\u60E8\\u6848","\\u6C11\\u56FD","\\u53F2\\u6599\\u5F85\\u8003"]','2026-09-11 08:31:05.246120','2026-09-16 09:31:28.606141');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('3c667a42ad8d4e26be657d98283dfd2c','第二次厚和惨案','厚和惨案（第二次）','惨案','民国','1937','绥远省','归绥（今呼和浩特）','厚和（今内蒙古呼和浩特市）','0','30','第二次厚和惨案指1937年日军侵占归绥（厚和）前后对当地民众的屠杀与暴行。1937年10月，日军关东军察哈尔派遣兵团等部攻占绥远省归绥（厚和豪特，今呼和浩特），在占领过程中及占领初期，对城内及周边居民实施搜捕、屠杀、奸淫和纵火，造成大量平民伤亡。因史料记载零散，具体遇难人数无确切统计，一般与第一次厚和惨案并称，反映日军在绥远地区的侵略暴行。该事件是抗日战争时期日军在内蒙古中西部制造的一系列惨案之一，对当地社会造成严重破坏。','["\\u7B2C\\u4E8C\\u6B21\\u539A\\u548C\\u60E8\\u6848","\\u539A\\u548C","\\u5F52\\u7EE5","\\u547C\\u548C\\u6D69\\u7279","\\u7EE5\\u8FDC","\\u6297\\u65E5\\u6218\\u4E89","\\u65E5\\u519B\\u66B4\\u884C"]','2026-09-11 09:30:28.470844','2026-09-16 09:32:21.074379');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('54ff2ada0ec152c1998f49a7d753fd1e','嘉定三屠','嘉定之屠','屠城惨案','明末','1645','江苏省','嘉定县','嘉定县城（今上海市嘉定区）','0','0','嘉定三屠指清顺治二年（1645年）清军攻破嘉定后对城中居民进行的三次大规模屠杀。是年六月，清廷颁布剃发令，激起江南反抗。闰六月，嘉定士民在侯峒曾、黄淳耀等人领导下据城抗清。七月，清军将领李成栋率部攻破嘉定，第一次屠城，死者甚众。此后，朱瑛、吴之番等又先后率众反抗，清军再次入城屠杀，前后共三次，史称“嘉定三屠”。屠杀持续数日，城中百姓死伤惨重，具体人数无确切统计，后世多称死者数万。嘉定三屠与扬州十日同为清初江南抗清斗争中的重大惨案，反映了明清易代之际的社会动荡与民族冲突，具有重要的历史警示意义。','["\\u5609\\u5B9A\\u4E09\\u5C60","\\u6E05\\u521D\\u5C60\\u57CE","\\u5243\\u53D1\\u4EE4","\\u4FAF\\u5CD2\\u66FE","\\u9EC4\\u6DF3\\u8000","\\u674E\\u6210\\u680B","\\u6C5F\\u5357\\u6297\\u6E05"]','2026-09-11 08:31:05.246120','2026-09-16 09:34:37.380803');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('5da664c9b26d59c8a3e3e555c1e55483','芜湖城内大屠杀','芜湖惨案','日军屠杀惨案','抗日战争时期','1937','安徽省','芜湖市','芜湖城内（今安徽省芜湖市镜湖区一带）','0','1','1937年12月，日军攻占南京前后，其第18师团等部沿长江南岸进攻芜湖。12月10日前后，日军攻陷芜湖城区，随即在城内及沿江一带进行大规模搜捕与屠杀，杀害未及撤离的中国守军伤兵、警察及平民，奸淫掳掠，焚烧房屋。据当时报刊、亲历者回忆及后世调查，遇难者数以千计，具体数字因史料散佚而难以确证。芜湖沦陷后，日军长期盘踞，城内人口锐减，工商业凋敝，成为日军在皖南实施暴行的典型地区之一。该惨案是南京大屠杀外围暴行的重要组成部分，反映了日军侵华期间对长江下游城市的系统性破坏。','["\\u829C\\u6E56","\\u6297\\u65E5\\u6218\\u4E89","\\u65E5\\u519B\\u66B4\\u884C","\\u5357\\u4EAC\\u5927\\u5C60\\u6740","\\u5B89\\u5FBD\\u6CA6\\u9677","1937\\u5E74"]','2026-09-11 08:31:05.246120','2026-09-16 09:31:12.189077');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('61349ac053fa5bcab1b80682a847e560','王厂沟惨案','','惨案','抗日战争时期','1941','河北省','承德市','宽城满族自治县王厂沟村','0','1','王厂沟惨案是抗日战争时期日军在冀东地区制造的一起屠杀事件。王厂沟村位于今河北省承德市宽城满族自治县境内，地处长城北侧、冀东抗日根据地边缘。1941年前后，日军为摧毁冀东抗日根据地、切断八路军与民众的联系，对长城沿线村庄反复进行“扫荡”和“集家并村”。日军闯入王厂沟，烧毁民房、抢掠财物，屠杀村民，造成大量无辜百姓伤亡，村庄几近被毁。由于现存公开史料对具体日期、死难人数记载不一，本条目暂不填写确切数字。该惨案是日军在冀东推行“治安强化运动”和制造“无人区”过程中犯下暴行的组成部分，与潘家峪惨案等共同构成冀东抗战时期民众苦难的历史记忆。','["\\u738B\\u5382\\u6C9F\\u60E8\\u6848","\\u5180\\u4E1C","\\u5BBD\\u57CE","\\u6297\\u65E5\\u6218\\u4E89","\\u65E5\\u519B\\u626B\\u8361","\\u96C6\\u5BB6\\u5E76\\u6751","\\u65E0\\u4EBA\\u533A"]','2026-09-11 08:31:05.246120','2026-09-16 09:31:07.033133');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('6178d256733356119915c4c47cdfae3d','无人区惨案','长城沿线无人区惨案','日军制造无人区暴行','抗日战争时期','1942','河北省','承德市','长城沿线（冀东、热河一带）','0','1','无人区惨案指抗日战争时期侵华日军在长城沿线冀东、热河等地强制制造“无人区”过程中屠杀、驱赶中国民众的暴行。1941年至1944年间，日军为切断中国共产党领导的抗日武装与民众联系，在长城两侧划定“无人区”，强迫居民迁出，焚毁村庄房屋，屠杀未及迁移或反抗的百姓，并设立“人圈”集中管制。据史料记载，仅冀东地区被毁村庄数以千计，数十万民众流离失所，大量平民在驱赶、冻饿和屠杀中死亡。该暴行是日军“治安强化运动”的重要组成部分，造成严重人口损失与社会破坏。','["\\u65E0\\u4EBA\\u533A","\\u957F\\u57CE\\u6CBF\\u7EBF","\\u65E5\\u519B\\u66B4\\u884C","\\u5180\\u4E1C","\\u70ED\\u6CB3","\\u4EBA\\u5708","\\u6297\\u65E5\\u6218\\u4E89"]','2026-09-11 08:31:05.246120','2026-09-16 09:31:01.914002');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('66e792a65eba5b9a804accf5a11ad088','南京大屠杀','南京大屠杀惨案、南京事件','屠杀惨案','抗日战争时期','1937','江苏省','南京市','南京城区及近郊','0','300000','1937年12月13日，侵华日军攻陷南京后，在华中派遣军司令松井石根等指挥下，对已放下武器的中国战俘和手无寸铁的平民实施长达六周的大规模屠杀、强奸、纵火与抢劫。日军在汉中门、草鞋峡、燕子矶、下关等地集体屠杀中国军民，并零散杀害市民，遇难者总数达三十万以上。同时发生大量强奸、轮奸暴行，无数妇女受害，全城三分之一建筑被毁。1946年远东国际军事法庭和南京审判战犯军事法庭对相关战犯进行审判，认定屠杀事实。南京大屠杀是二战期间最严重的战争暴行之一，成为中国人民抗日战争和世界反法西斯战争的重要历史记忆。','["\\u5357\\u4EAC\\u5927\\u5C60\\u6740","\\u4FB5\\u534E\\u65E5\\u519B","1937\\u5E74","\\u4E09\\u5341\\u4E07\\u9047\\u96BE\\u8005","\\u5357\\u4EAC\\u4FDD\\u536B\\u6218","\\u8FDC\\u4E1C\\u56FD\\u9645\\u519B\\u4E8B\\u6CD5\\u5EAD","\\u6297\\u65E5\\u6218\\u4E89"]','2026-09-11 08:31:05.246120','2026-09-16 09:30:51.574136');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('67ec001cd90a5142a909f76afc2e03ea','吴三桂弑永历','永历帝被弑、咒水之难后永历遇害','政治谋杀','明末','1662','云南省','昆明市','昆明篦子坡（逼死坡）','0','1','1662年（清康熙元年，南明永历十六年），南明末代皇帝朱由榔在云南昆明被吴三桂处死。1661年清军攻入云南，永历帝逃入缅甸，被缅王莽白拘禁。同年吴三桂率清军入缅，缅方交出永历帝及其眷属。1662年4月，永历帝被押回昆明，吴三桂不顾旧主之情，奏请清廷就地正法，最终以弓弦将永历帝及其子朱慈煊等缢死于昆明篦子坡（后称逼死坡）。永历帝之死标志着南明政权的彻底覆灭，吴三桂因弑君背负历史骂名，篦子坡亦成为后世凭吊南明亡国的历史遗迹。','["\\u5434\\u4E09\\u6842","\\u6C38\\u5386\\u5E1D","\\u5357\\u660E","\\u6606\\u660E","\\u7BE6\\u5B50\\u5761","\\u5492\\u6C34\\u4E4B\\u96BE","\\u5F11\\u541B"]','2026-09-11 08:31:05.246120','2026-09-16 09:34:29.638758');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('683f1113d7a854dabf10d40244f09a14','洪山惨案','','惨案','抗日战争时期','1939','湖北省','随州市','洪山镇','0','1','洪山惨案是抗日战争时期日军在湖北省随县洪山镇（今随州市洪山镇）制造的一起屠杀事件。1939年，日军侵占随县地区后，对洪山一带进行扫荡，屠杀当地居民，焚烧房屋，造成人员伤亡和财产损失。具体遇难人数史料记载不一，有待进一步考证。该惨案是日军在鄂北地区侵略暴行的组成部分，反映了抗战时期沦陷区民众的苦难。','["\\u6D2A\\u5C71\\u60E8\\u6848","\\u968F\\u53BF","\\u6D2A\\u5C71\\u9547","\\u65E5\\u519B\\u66B4\\u884C","\\u6297\\u65E5\\u6218\\u4E89","\\u9102\\u5317"]','2026-09-11 08:31:05.246120','2026-09-16 09:30:43.304072');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('689bebc26ff853bab9995985cca50488','日军制造多起惨案','','侵略暴行','抗日战争时期','1937','山东','济宁','山东 济宁','1','29','抗日战争期间，侵华日军在占领区系统性制造了大量屠杀、扫荡、轰炸等惨案，造成中国军民巨大伤亡。典型如1937年南京大屠杀，日军攻陷南京后展开长达六周的大规模屠杀、强奸与纵火，遇难者逾三十万；华北地区推行“治安肃正”与“三光作战”，在潘家峪、北疃、平阳等地制造多起集体屠杀；华东、华中地区亦频发清乡与扫荡暴行。这些事件构成日本侵华战争暴行的整体图景，是研究抗战史与战争罪责的重要史料。','["\\u6297\\u65E5\\u6218\\u4E89","\\u65E5\\u519B\\u66B4\\u884C","\\u60E8\\u6848","\\u5357\\u4EAC\\u5927\\u5C60\\u6740","\\u4E09\\u5149\\u4F5C\\u6218","\\u626B\\u8361","\\u6218\\u4E89\\u7F6A\\u8D23"]','2026-09-11 08:31:05.246120','2026-09-16 09:30:37.837879');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('75bb4a557824574eb5c2a65fbcbd32d5','大西庄惨案','','惨案','抗日战争时期','1937','山西','阳泉','大西庄','0','1','大西庄惨案是抗日战争时期发生在华北地区的一起日军屠杀平民事件，具体时间与地点因史料记载有限尚待进一步考证。据相关地方志与抗战史料线索，日军在扫荡或清乡行动中于大西庄一带对当地居民实施暴力，造成人员伤亡与财产损失，村庄遭到严重破坏。此类惨案是日军侵华期间在华北推行“治安强化运动”和反复扫荡的缩影，给当地民众带来深重灾难。由于现存公开史料对该事件的时间、经过与确切伤亡数字记载不详，本条目暂按结构保留，相关细节有待档案与地方史料的进一步发掘核实。','["\\u5927\\u897F\\u5E84\\u60E8\\u6848","\\u6297\\u65E5\\u6218\\u4E89","\\u65E5\\u519B\\u66B4\\u884C","\\u534E\\u5317","\\u60E8\\u6848","\\u5730\\u65B9\\u5FD7"]','2026-09-11 08:31:05.246120','2026-09-16 09:30:31.239541');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('768a6e5ddd3c5297a75eeef91d6e30d5','十八人被杀惨案','','惨案','民国','1937','安徽','池州','安徽 池州','0','18','该名称所指事件在现存公开史料中缺乏明确、可考的记载，难以确定其具体发生时间、地点与经过。从名称判断，应为一处造成十八人死亡的屠杀或集体杀害事件，可能发生于民国时期或抗日战争时期，但现有资料不足以确认其归属。为避免编造史实，本条目暂不填写具体时间、地点与经过，仅保留事件名称与已知的死亡人数十八人。建议结合地方志、档案目录或相关学术论著进一步核实，以补充其确切背景与历史影响。','["\\u5341\\u516B\\u4EBA\\u88AB\\u6740","\\u60E8\\u6848","\\u6C11\\u56FD","\\u6297\\u65E5\\u6218\\u4E89","\\u5C60\\u6740","\\u53F2\\u6599\\u5F85\\u8003"]','2026-09-11 08:31:05.246120','2026-09-16 09:30:23.112267');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('77f952368a1452c8bba852ed00ec5536','反共誓约惨案','','惨案','民国','1937','河北','沧州','河北 沧州','0','2','反共誓约惨案是民国时期国民党当局在国共内战背景下，强制推行反共宣誓、对拒绝宣誓或涉嫌亲共人员实施迫害的事件。由于该名称并非学界广泛使用的标准历史事件称谓，具体发生时间、地点、经过及伤亡人数缺乏可靠、统一的史料记载，难以确证。相关背景是抗战胜利后国民党为巩固统治，在部分收复区及国统区推行联保连坐与反共宣誓，对中共地下组织及进步群众进行清查。此类事件散见于地方档案与回忆录，但以“反共誓约惨案”为名的专门记录稀少，故本条目暂无法提供确切时间、地点与伤亡数据。伪职：伪任丘县县长；策划臭名昭著的反共誓约惨案，逼迫群众宣誓反共，残害大量平民百姓。；结局：1945 年公审判处死刑','["\\u53CD\\u5171\\u8A93\\u7EA6","\\u56FD\\u5171\\u5185\\u6218","\\u56FD\\u6C11\\u515A","\\u653F\\u6CBB\\u8FEB\\u5BB3","\\u5BA3\\u8A93","\\u6C11\\u56FD"]','2026-09-11 08:31:05.246120','2026-09-16 09:24:17.442090');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('7d5d39f9e4a35cc7a8cdac5ff4ac4e2b','后马家村惨案','','惨案','抗日战争时期','1938','山东省','枣庄市','滕县（今滕州市）后马家村','0','100','后马家村惨案是抗日战争时期日军在山东滕县制造的一起屠杀事件。1938年3月至4月，日军第十师团等部进攻滕县，遭到中国守军顽强抵抗。滕县失陷后，日军对周边村庄进行报复性扫荡。据地方史志记载，日军窜入后马家村，屠杀无辜村民，焚毁房屋，造成人员伤亡和财产损失。具体遇难人数因史料记载不一，尚待进一步考证。该惨案是日军在鲁南地区侵略暴行的组成部分，反映了抗战初期日军在占领区实施烧杀抢掠的历史事实，也是当地民众抗战苦难记忆的重要见证。','["\\u540E\\u9A6C\\u5BB6\\u6751","\\u6ED5\\u53BF","\\u65E5\\u519B\\u66B4\\u884C","\\u6297\\u65E5\\u6218\\u4E89","\\u5C71\\u4E1C\\u60E8\\u6848","\\u9C81\\u5357"]','2026-09-11 08:31:05.246120','2026-09-16 09:34:00.308084');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('7ee8d0b2e2d954fa8c51a638881d5a5e','九一八事变','沈阳事变、奉天事变、柳条湖事件','军事侵略事变','民国','1931','辽宁省','沈阳市','柳条湖、北大营、沈阳城','1','0','1931年9月18日夜，日本关东军自行炸毁沈阳北郊柳条湖附近南满铁路路轨，反诬中国军队所为，随即炮轰东北军北大营，进攻沈阳城，制造九一八事变。由于东北当局执行不抵抗政策，日军在短时间内占领沈阳及东北多地，至1932年2月东北全境沦陷，随后扶植成立伪满洲国。事变标志着日本大规模侵华战争的开始，也是中国人民抗日战争的起点，东北民众自发组织抗日义勇军等武装抵抗，揭开东北十四年抗战的序幕。','["\\u4E5D\\u4E00\\u516B\\u4E8B\\u53D8","\\u67F3\\u6761\\u6E56\\u4E8B\\u4EF6","\\u5173\\u4E1C\\u519B","\\u4E1C\\u5317\\u6CA6\\u9677","\\u6297\\u65E5\\u6218\\u4E89\\u8D77\\u70B9","\\u4E0D\\u62B5\\u6297\\u653F\\u7B56","\\u4F2A\\u6EE1\\u6D32\\u56FD"]','2026-09-11 08:31:05.246120','2026-09-16 09:34:17.446747');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('846bc680e83656e0b7c84eb49610e452','桑矾救国会惨案','','惨案','民国','1940','河北','张家口','河北 张家口','0','1','桑矾救国会惨案所指事件及具体时间、地点、经过与伤亡情况，目前缺乏可靠可考的史料记载，暂无法确认其确切内容。该名称可能为地方性抗日救国会相关事件，或系名称讹传、异写，有待进一步查证。','["\\u6851\\u77FE","\\u6551\\u56FD\\u4F1A","\\u60E8\\u6848","\\u6C11\\u56FD","\\u6297\\u65E5\\u6551\\u4EA1"]','2026-09-11 08:31:05.246120','2026-09-16 09:32:53.244964');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('857d72519c2d5a40be89425a22981f8e','潘家峪惨案','潘家峪大屠杀','惨案','抗日战争时期','1941','河北省','唐山市丰润区','潘家峪村','0','1230','1941年1月25日（农历腊月二十八），侵华日军驻唐山部队在佐佐木二郎指挥下，纠集丰润、遵化、玉田等县日伪军3000余人，包围冀东抗日根据地丰润县潘家峪村。日军将全村1500余名村民驱赶到村西大坑，后逼入潘家大院，用机枪扫射、纵火焚烧，并挨家挨户搜杀。屠杀持续至次日，全村1230人遇难，其中妇女儿童约650人，31户被杀绝，房屋1100余间被烧毁，牲畜财物被劫掠一空。惨案发生后，冀东军民组建复仇团继续抗日。潘家峪惨案是日军在华北推行‘治安强化运动’期间制造的重大屠杀事件，成为侵华日军暴行的铁证。','["\\u6F58\\u5BB6\\u5CEA\\u60E8\\u6848","\\u6F58\\u5BB6\\u5CEA\\u5927\\u5C60\\u6740","\\u5180\\u4E1C\\u6297\\u65E5\\u6839\\u636E\\u5730","\\u4F50\\u4F50\\u6728\\u4E8C\\u90CE","\\u65E5\\u519B\\u66B4\\u884C","\\u6CBB\\u5B89\\u5F3A\\u5316\\u8FD0\\u52A8","\\u4E30\\u6DA6"]','2026-09-11 08:31:05.246120','2026-09-16 09:32:35.425018');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('897767c44bc4548784f177d0b52e2151','下五家子惨案','下五家子惨案','惨案','民国','1936','辽宁省','朝阳市','朝阳县下五家子村','0','1','下五家子惨案发生于民国二十五年（1936年）前后，地点在辽宁省朝阳县下五家子村一带。九一八事变后，日本关东军侵占热河、辽宁地区，对抗日武装活动区域实施残酷镇压。据地方史志与幸存者回忆，日军以搜查抗日武装为名，对下五家子村及附近村落进行清剿，杀害无辜村民，焚毁房屋，造成重大人员伤亡和财产损失。该惨案是日军在辽宁朝阳地区制造的众多暴行之一，反映了日本侵略者在东北推行“治安肃正”政策、以血腥手段镇压民众的史实。具体遇难人数与细节因史料记载不一，尚待进一步考证。','["\\u4E0B\\u4E94\\u5BB6\\u5B50\\u60E8\\u6848","\\u8FBD\\u5B81\\u671D\\u9633","\\u65E5\\u519B\\u66B4\\u884C","\\u4E5D\\u4E00\\u516B\\u4E8B\\u53D8","\\u4E1C\\u5317\\u6297\\u6218","\\u6CBB\\u5B89\\u8083\\u6B63"]','2026-09-11 08:31:05.246120','2026-09-16 09:34:08.500475');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('8a7a5673727d5a75b27a5d8fb6a27135','甲申国难','甲申之变、崇祯殉国','王朝更替与战乱','明末','1644','北京','','北京及华北等地','1','0','甲申国难指1644年（明崇祯十七年、干支甲申）明朝灭亡及随之而来的大规模战乱与社会动荡。是年正月，李自成在西安建立大顺政权，随后东渡黄河，经山西直逼北京。三月十九日，大顺军攻入北京内城，崇祯帝自缢于煤山，明朝中央政权覆灭。不久，吴三桂引清军入关，在山海关击败李自成，清军进占北京并逐步南下。此后数年间，华北、江南等地战火蔓延，南明诸政权相继覆亡，清廷推行剃发易服等政策，引发江阴、嘉定等地抗清斗争与屠城事件，民众死伤惨重。甲申国难不仅标志明朝终结，也开启清朝对全国的统治，对17世纪中国政治格局、社会结构与人口造成深远影响。','["\\u7532\\u7533\\u56FD\\u96BE","\\u7532\\u7533\\u4E4B\\u53D8","\\u5D07\\u796F\\u6B89\\u56FD","\\u674E\\u81EA\\u6210","\\u6E05\\u519B\\u5165\\u5173","\\u660E\\u671D\\u706D\\u4EA1","1644\\u5E74"]','2026-09-11 08:31:05.246120','2026-09-16 09:34:51.614936');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('9022c58712be5b00af860625bbf3e34b','建昌药王庙惨案','','惨案','民国','1937','辽宁省','建昌县','药王庙','0','1','建昌药王庙惨案是民国时期发生在辽宁省建昌县药王庙一带的一起屠杀事件。据地方史志资料记载，日军或地方武装在该地制造惨案，造成当地民众伤亡。
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('907016a3edc252078480f1135a8e9f04','民间惨案','','惨案','','1937','安徽','安庆','安徽 安庆','0','1','“民间惨案”并非一个具有明确时间、地点与经过的特定历史事件名称，而是对民间所遭受各类惨案的一种泛称或统称。在民国与抗日战争时期，中国各地曾发生大量针对平民的屠杀、轰炸、扫荡等暴行，如南京大屠杀、潘家峪惨案、平顶山惨案等，均可归入广义的民间惨案范畴。由于该名称所指不明确，无法对应单一可考事件，故本条目暂不展开具体叙述。如需整理，请提供更具体的事件名称或时间、地点信息。','["\\u6C11\\u95F4\\u60E8\\u6848","\\u6C11\\u56FD","\\u6297\\u65E5\\u6218\\u4E89","\\u5E73\\u6C11\\u4F24\\u4EA1","\\u6CDB\\u79F0"]','2026-09-11 08:31:05.246120','2026-09-16 09:24:52.697323');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('94af8984a8b854e9a54a9e983e8d71eb','旅顺大屠杀','旅顺惨案','屠杀惨案','清末','1894','辽宁省','大连市','旅顺口区','0','20000','1894年11月21日，日军攻陷旅顺口后，对城内居民进行了持续数日的大规模屠杀。据当时中外目击者、随军记者及西方报刊记载，日军挨户搜查，逢人便杀，老幼妇孺亦难幸免，遇难者约两万人，全城仅存数十人掩埋尸体。屠杀发生后，美国《纽约世界报》等外媒予以报道，引发国际舆论震动。旅顺大屠杀是甲午战争期间日军制造的重大暴行之一，也是近代史上日军首次大规模屠城事件，成为后续日本侵华暴行的先声，具有重要的史料与警示价值。','["\\u65C5\\u987A\\u5927\\u5C60\\u6740","\\u7532\\u5348\\u6218\\u4E89","\\u65E5\\u519B\\u66B4\\u884C","\\u65C5\\u987A\\u53E3","1894\\u5E74","\\u5C60\\u57CE"]','2026-09-11 08:31:05.246120','2026-09-16 09:22:46.486117');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('9cc3cd8a133c5809923316c28e4e775f','本溪胡家村惨案','','惨案','抗日战争时期','1936','辽宁省','本溪市','本溪县胡家村（今辽宁省本溪市境内）','0','1','本溪胡家村惨案是抗日战争时期日本侵略者在辽宁本溪地区制造的一起屠杀事件。据地方史料记载，1936年前后，日本关东军及伪满军警以“清剿抗日武装”为名，对本溪县胡家村一带进行扫荡，逮捕并杀害当地村民，焚毁房屋，造成人员伤亡和财产损失。该惨案是日军在东北推行“治安肃正”和“集团部落”政策期间，对抗日根据地周边民众实施暴力镇压的组成部分。由于现存档案与亲历者证言有限，具体遇难人数、确切日期等细节尚待进一步考证。该事件反映了东北沦陷时期民众遭受的战争苦难，是研究本溪地区抗战史和日军暴行的重要个案。','["\\u672C\\u6EAA","\\u80E1\\u5BB6\\u6751\\u60E8\\u6848","\\u6297\\u65E5\\u6218\\u4E89","\\u65E5\\u519B\\u66B4\\u884C","\\u4E1C\\u5317\\u6CA6\\u9677\\u533A","\\u6CBB\\u5B89\\u8083\\u6B63"]','2026-09-11 08:31:05.246120','2026-09-16 09:24:45.074289');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('a725f058493f5f448df12b8b8de175e7','黄土桥惨案','','惨案','抗日战争时期','1937','江苏省','无锡市','无锡县黄土桥（今无锡市惠山区一带）','0','2','黄土桥惨案是抗日战争初期日军在江苏无锡制造的屠杀事件。1937年11月，日军攻占上海后沿沪宁线西进，11月下旬侵占无锡。日军在无锡城乡进行大规模烧杀淫掠，黄土桥一带的村民亦遭波及。据地方史料记载，日军在黄土桥附近搜捕青壮年，将数十名村民集中杀害，并焚烧民房，造成当地民众重大伤亡和财产损失。由于相关档案与口述史料记载较为零散，具体遇难人数存在不同说法，尚待进一步考证。该惨案是日军侵占无锡期间暴行的一部分，与同期无锡城乡多起屠杀事件共同构成日军在苏南地区的战争罪行，是研究无锡沦陷史和日军暴行的重要个案。','["\\u9EC4\\u571F\\u6865\\u60E8\\u6848","\\u65E0\\u9521","\\u65E5\\u519B\\u66B4\\u884C","\\u6297\\u65E5\\u6218\\u4E89","1937\\u5E74","\\u82CF\\u5357","\\u5C60\\u6740"]','2026-09-11 08:31:05.246120','2026-09-16 09:24:36.680342');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('aa48a20c89b855cb9a1621dec972e889','大胡庄惨案','大胡庄战斗','惨案','抗日战争时期','1941','江苏省','淮安市','淮安区苏嘴镇大胡庄','0','82','1941年4月，新四军第三师八旅二十四团一营二连在江苏省淮安县大胡庄（今淮安市淮安区苏嘴镇）执行任务时，遭日伪军包围。全连指战员在连长、指导员带领下奋起抵抗，与敌激战数小时，终因寡不敌众，除一名战士负伤后隐蔽幸存外，其余82人全部壮烈牺牲。此战是抗日战争时期苏北地区新四军成建制连队损失最为惨重的战斗之一，展现了新四军将士宁死不屈的民族气节。战后当地民众将烈士遗骸集中安葬，并修建纪念碑。大胡庄惨案是日军在苏北地区实施残酷扫荡、屠杀抗日武装的典型暴行，也是研究苏北抗日斗争史的重要事件。','["\\u5927\\u80E1\\u5E84\\u60E8\\u6848","\\u65B0\\u56DB\\u519B","\\u82CF\\u5317\\u6297\\u65E5","\\u6DEE\\u5B89","1941\\u5E74","\\u65E5\\u4F2A\\u519B","82\\u70C8\\u58EB"]','2026-09-11 08:31:05.246120','2026-09-16 09:24:25.974469');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('ad335e78c8835046b598718227395d3f','白家辛庄惨案','','惨案','抗日战争时期','1937','山西','朔州','山西 朔州','0','1','伪职：五地委秘书叛变，大特务；罪行：核心叛徒，出卖情报酿成白家辛庄惨案，168 名抗日干部学员遇难，是雁北重大惨案祸首之一。；结局：解放后公审枪决。
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('af1ca566ceae5c39b7ebeb15ea97a0e7','令公庙惨案','','惨案','抗日战争时期','1937','江西','南昌','江西 南昌','0','1','伪职：汉奸向导；罪行：1942年令公庙大屠杀带路元凶，带领日军制造860余人惨死的惨案；结局：战后被依法处决','[]','2026-09-11 08:31:05.246120','2026-09-11 08:31:05.246120');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('b06f8b29654f42d7a257a553aaaae8dc','厚和大惨案','厚和惨案','惨案','民国','1937','绥远省','归绥县（今内蒙古自治区呼和浩特市）','厚和（今呼和浩特市）','0','0','地点：伪蒙疆政权厚和豪特市（即今天的内蒙古呼和浩特，旧称归绥）。
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('b5376452ffb0535dbe4e4926d498da2d','泊里大屠杀惨案','泊里惨案','屠杀惨案','抗日战争时期','1945','山东省','青岛市黄岛区（原胶南县）','泊里镇','0','0','泊里大屠杀惨案是抗日战争时期日军在山东胶南泊里地区制造的一起屠杀事件。1945年，日军在投降前夕对泊里一带进行扫荡，对当地抗日军民和无辜群众实施屠杀、烧毁房屋、抢掠财物，造成大量人员伤亡和财产损失。具体遇难人数因史料记载不一，暂无确切统计。该惨案是日军侵华期间在山东地区犯下的暴行之一，反映了侵略战争给中国人民带来的深重灾难。','["\\u6CCA\\u91CC\\u5927\\u5C60\\u6740","\\u6CCA\\u91CC\\u60E8\\u6848","\\u6297\\u65E5\\u6218\\u4E89","\\u5C71\\u4E1C","\\u80F6\\u5357","\\u65E5\\u519B\\u66B4\\u884C"]','2026-09-11 08:31:05.246120','2026-09-16 09:23:59.081737');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('cc812b6ab8bc567d925a6f7586d54607','插箭岭屠杀','','屠杀惨案','抗日战争时期','1937','河北省','涞源县','插箭岭及周边村庄','0','1','插箭岭屠杀是抗日战争初期日军在河北省涞源县插箭岭一带制造的屠杀事件。1937年秋，日军沿平汉线及太行山北部推进，在涞源地区遭到中国军队抵抗后，对插箭岭及附近村庄实施报复性扫荡，杀害无辜村民，焚烧房屋，抢掠牲畜粮食，造成当地民众大量伤亡和流离失所。具体遇难人数因史料记载不一，暂无确切统计。该事件是日军在华北敌后战场推行烧杀抢掠政策、制造无人区暴行的组成部分，反映了抗战时期华北乡村民众所遭受的深重灾难。','["\\u63D2\\u7BAD\\u5CAD","\\u6D9E\\u6E90","\\u6297\\u65E5\\u6218\\u4E89","\\u65E5\\u519B\\u66B4\\u884C","\\u534E\\u5317\\u626B\\u8361","\\u5C60\\u6740\\u60E8\\u6848"]','2026-09-11 08:31:05.246120','2026-09-16 09:23:45.507365');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('cec7c4759f155852a08385701357bc03','三十二烈士惨案','','惨案','民国','1937','黑龙江','大庆','黑龙江 大庆','0','32','三十二烈士惨案是民国时期发生的一起集体杀害事件，因遇难者人数为三十二人而得名。
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('d56e0c215d91579c957d7dd650cfc567','崖山之战','崖山海战、崖门海战','战役','宋末','1279','广东省','江门市','新会区崖门镇崖门水道','0','100000','崖山之战是南宋末年宋元之间的最后一场大规模海战。1279年（南宋祥兴二年、元至元十六年），元将张弘范率水军追击南宋残部，宋军由张世杰、陆秀夫等率领，拥立幼帝赵昺，退守广东新会崖山。双方在崖门水道展开决战，元军以火攻、封锁等手段大败宋军。宋军战船多被焚毁，陆秀夫负幼帝赵昺投海殉国，张世杰突围后遇风浪溺亡，南宋覆灭。此役死亡及投海者甚众，史载浮尸十余万，标志着宋朝的终结和元朝统一全国。','["\\u5D16\\u5C71\\u4E4B\\u6218","\\u5357\\u5B8B","\\u5143\\u671D","\\u5F20\\u5F18\\u8303","\\u9646\\u79C0\\u592B","\\u8D75\\u663A","\\u5D16\\u95E8","\\u6D77\\u6218"]','2026-09-11 08:31:05.246120','2026-09-16 09:35:02.568696');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('d732f80acb215113ab7264d4ce168d59','大华饭店大轰炸惨案','','轰炸惨案','抗日战争时期','1937','上海市','上海市','大华饭店（今上海市黄浦区南京东路一带）','0','1','1937年淞沪会战期间，上海华界与租界交界地带屡遭日军及中国空军轰炸波及。大华饭店位于上海闹市区，在八一三事变后的空袭中遭炸弹击中，造成人员伤亡。该事件属于淞沪会战期间上海平民遭受空袭的惨案之一，具体时间、投弹方及确切伤亡人数因史料记载有限，尚待进一步考证。','["\\u5927\\u534E\\u996D\\u5E97","\\u4E0A\\u6D77\\u5927\\u8F70\\u70B8","\\u6DDE\\u6CAA\\u4F1A\\u6218","\\u7A7A\\u88AD\\u60E8\\u6848","1937\\u5E74","\\u5E73\\u6C11\\u4F24\\u4EA1"]','2026-09-11 08:31:05.246120','2026-09-16 09:27:22.841211');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('e5b611ae9e9c5768954110fcdaed86c7','扬州十日','扬州屠城','屠城惨案','明末','1645','江苏省','扬州市','扬州城','0','800000','扬州十日指清顺治二年（南明弘光元年，1645年）四月清军攻破扬州城后，对城中军民进行的大规模屠杀。是年四月，清豫亲王多铎率军围攻扬州，南明督师史可法坚守孤城，拒降死守。四月二十五日城破，史可法被俘遇害。清军入城后展开持续多日的屠戮，据王秀楚《扬州十日记》等私家记载，屠杀自四月二十五日延续至五月初，死者甚众，焚尸簿所载约八十万，实际数字学界有争议。此次屠城为明清易代之际清军南下过程中的重大暴行之一，与嘉定三屠、江阴八十一日等并称，对江南社会造成严重破坏，亦成为后世记述南明抗清与清初民族冲突的重要史料。','["\\u626C\\u5DDE\\u5341\\u65E5","\\u626C\\u5DDE\\u5C60\\u57CE","\\u53F2\\u53EF\\u6CD5","\\u591A\\u94CE","\\u5357\\u660E","\\u626C\\u5DDE\\u5341\\u65E5\\u8BB0","\\u6E05\\u519B\\u5357\\u4E0B","\\u4E59\\u9149"]','2026-09-11 08:31:05.246120','2026-09-16 09:34:45.065687');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('e736bf7cefff5670a74672f1689bbebb','朔县惨案','朔县屠城','日军屠杀惨案','抗日战争时期','1937','山西省','朔州市朔城区','山西省朔县城（今朔州市朔城区）','0','3800','朔县惨案是抗日战争初期日军在山西省朔县制造的一起大规模屠杀事件。1937年9月，日军关东军察哈尔派遣兵团沿平绥铁路西进，于9月26日前后攻陷朔县城。日军入城后，对城内居民和已放下武器的中国守军进行持续数日的搜捕与屠杀，采用枪杀、刺刀挑杀、集体活埋等残忍手段，遇难者达三千余人，城内房屋亦被大量焚毁。此次屠杀是日军在晋北地区继天镇、阳高惨案之后制造的又一起严重暴行，与同期发生的灵丘、宁武等惨案共同构成日军侵占山西初期的一系列屠杀事件，造成当地人口锐减、社会秩序崩溃，成为日军侵华暴行的铁证之一。','["\\u6714\\u53BF\\u60E8\\u6848","\\u6714\\u53BF\\u5C60\\u57CE","\\u5C71\\u897F\\u6714\\u53BF","1937\\u5E74","\\u65E5\\u519B\\u66B4\\u884C","\\u664B\\u5317\\u60E8\\u6848","\\u6297\\u65E5\\u6218\\u4E89"]','2026-09-11 08:31:05.246120','2026-09-16 09:27:16.474524');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('f080f93b04255403b1b49a01d15362b3','杨湾惨案','','惨案','抗日战争时期','1943','江苏省','淮安市','淮安区杨湾村','0','2','杨湾惨案是抗日战争时期日军在江苏省淮安县（今淮安市淮安区）杨湾村制造的一起屠杀事件。1943年前后，日军在苏北地区频繁扫荡，搜捕抗日武装与地方民众。据地方史料记载，日军窜入杨湾村后，对村民实施烧杀抢掠，造成多人伤亡，房屋被焚毁，民众财产遭受严重损失。由于现存档案与方志记载较为简略，具体遇难人数与确切日期尚待进一步考证。该惨案是日军在苏北地区推行“清乡”“扫荡”政策、残害平民的罪证之一，反映了抗战时期沦陷区民众的深重苦难。','["\\u6768\\u6E7E\\u60E8\\u6848","\\u6297\\u65E5\\u6218\\u4E89","\\u82CF\\u5317","\\u6DEE\\u5B89","\\u65E5\\u519B\\u66B4\\u884C","\\u6E05\\u4E61\\u626B\\u8361"]','2026-09-11 08:31:05.246120','2026-09-16 09:27:10.885593');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('f71786b8956f56068a40f4254fef7c14','门楼下惨案','','惨案','抗日战争时期','1937','江苏','无锡','江苏 无锡','0','1','门楼下惨案是抗日战争时期日军在华北地区制造的一起屠杀事件，具体发生时间与地点因史料记载有限尚待进一步考证。据现有资料，日军在扫荡过程中于门楼下村一带对当地民众实施屠杀，造成人员伤亡和财产损失。该惨案是日军侵华期间在敌后抗日根据地推行烧光、杀光、抢光政策的具体罪证之一，反映了侵略战争给中国人民带来的深重灾难。由于相关档案与地方志记载较为零散，事件的确切时间、地点及伤亡人数仍需结合更多原始史料加以核实。','["\\u95E8\\u697C\\u4E0B\\u60E8\\u6848","\\u6297\\u65E5\\u6218\\u4E89","\\u65E5\\u519B\\u66B4\\u884C","\\u534E\\u5317","\\u5C60\\u6740","\\u626B\\u8361"]','2026-09-11 08:31:05.246120','2026-09-16 09:26:59.831780');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('fae2f53fd73b52d385c461ebf7c1c586','安东教育救国会惨案','安东教育界惨案','惨案','民国','1936','辽宁省','丹东市','安东县（今丹东市）','0','1','安东教育救国会惨案是九一八事变后日本关东军与伪满当局在安东（今辽宁丹东）对教育界爱国人士进行的大规模逮捕与屠杀事件。1935年至1936年间，安东教育界人士秘密组织教育救国会，从事抗日宣传与联络活动。1936年，日伪军警在安东及周边地区展开大搜捕，逮捕教育界人士及学生数百人，其中多人被酷刑折磨致死或被杀害，具体遇难人数史料记载不一。该惨案使安东地区教育界抗日力量遭受严重摧残，是日本侵略者在东北镇压抗日爱国运动的重要罪证之一。','["\\u5B89\\u4E1C\\u6559\\u80B2\\u6551\\u56FD\\u4F1A","\\u5B89\\u4E1C\\u60E8\\u6848","\\u4E39\\u4E1C","\\u6297\\u65E5\\u6551\\u56FD\\u4F1A","\\u4E1C\\u5317\\u6CA6\\u9677\\u533A","\\u6559\\u80B2\\u754C","\\u65E5\\u4F2A\\u9547\\u538B"]','2026-09-11 08:31:05.246120','2026-09-16 09:26:54.013961');
INSERT INTO `atrocitycases` (`Id`, `Name`, `Alias`, `EventType`, `Era`, `Year`, `Province`, `City`, `Location`, `IsGeneral`, `PersonCount`, `Summary`, `Keywords`, `CreatedAt`, `UpdatedAt`) VALUES ('fcaf68647e5158318b87277bb4408c20','范家湾惨案','','惨案','抗日战争时期','1940','山西省','忻州市','忻府区范家湾村','0','1','范家湾惨案是抗日战争时期日军在山西忻州制造的一起屠杀事件。1940年，侵华日军在晋北地区进行扫荡，于忻县（今忻州市忻府区）范家湾村一带对当地民众实施暴行，造成村民伤亡和财产损失。由于相关档案与口述史料有限，具体遇难人数、发生日期及详细经过尚待进一步考证。该惨案是日军在华北“治安肃正”作战期间残害平民的罪证之一，反映了抗战时期晋北民众所遭受的深重灾难。','["\\u8303\\u5BB6\\u6E7E\\u60E8\\u6848","\\u5FFB\\u5DDE","\\u5C71\\u897F","\\u6297\\u65E5\\u6218\\u4E89","\\u65E5\\u519B\\u66B4\\u884C","\\u60E8\\u6848"]','2026-09-11 08:31:05.246120','2026-09-16 09:26:46.753215');
